const memoryStore = {
  expenses: new Map(),
  notes: new Map(),
  todos: new Map(),
};

export async function saveRecord(collectionName, id, data) {
  memoryStore[collectionName].set(id, data);
}

export async function getRecord(collectionName, id) {
  return memoryStore[collectionName].get(id) ?? null;
}

export async function listRecords(collectionName) {
  return Array.from(memoryStore[collectionName].values());
}

export async function listByUser(collectionName, userId) {
  const records = await listRecords(collectionName);
  return records
    .filter((record) => record.userId === userId)
    .sort((a, b) => String(b.createdAt).localeCompare(String(a.createdAt)));
}

export function createId(prefix) {
  return `${prefix}_${Date.now().toString(36)}_${Math.random().toString(36).slice(2, 8)}`;
}

export function nowIso() {
  return new Date().toISOString();
}

export function today() {
  return nowIso().slice(0, 10);
}

