import fs from 'node:fs';
import path from 'node:path';

// 使用者傳來的照片/語音/檔案存在本機 data/media/，
// 透過 /media/:id 路由對外提供（Flex Message 的圖片必須是 https URL）。
const MEDIA_DIR = process.env.MEDIA_DIR || './data/media';
const INDEX_PATH = path.join(MEDIA_DIR, 'index.json');

const mediaIndex = new Map();
const lastImageByUser = new Map();

init();

function init() {
  fs.mkdirSync(MEDIA_DIR, { recursive: true });
  try {
    const saved = JSON.parse(fs.readFileSync(INDEX_PATH, 'utf-8'));
    for (const entry of saved) mediaIndex.set(entry.id, entry);
  } catch {
    // index 不存在或壞掉時從空索引開始
  }
}

function persistIndex() {
  try {
    fs.writeFileSync(INDEX_PATH, JSON.stringify([...mediaIndex.values()], null, 2));
  } catch (error) {
    console.warn(`Media index write failed: ${error.message}`);
  }
}

const EXT_BY_MIME = {
  'image/jpeg': '.jpg',
  'image/png': '.png',
  'image/webp': '.webp',
  'audio/m4a': '.m4a',
  'audio/x-m4a': '.m4a',
  'audio/mp4': '.m4a',
  'audio/aac': '.aac',
  'audio/mpeg': '.mp3',
  'video/mp4': '.mp4',
  'application/pdf': '.pdf',
  'text/plain': '.txt',
  'text/csv': '.csv',
  'text/vcard': '.vcf',
  'text/x-vcard': '.vcf',
};

mp4',
  'application/pdf': '.pdf',
  'text/plain': '.txt',
  'text/csv': '.csv',
  'text/vcard': '.vcf',
  'text/x-vcard': '.vcf',
};

export function saveMedia(buffer, mimeType, userId, fileName = '') {
  const id = `med_${Date.now().toString(36)}_${Math.random().toString(36).slice(2, 8)}`;
  const ext = EXT_BY_MIME[mimeType] || path.extname(fileName) || '.bin';
  const file = `${id}${ext}`;
  fs.writeFileSync(path.join(MEDIA_DIR, file), buffer);

const entry = { id, file, mimeType, userId, fileName, size: buffer.length, createdAt: new Date().toISOString() };
  mediaIndex.set(id, entry);
  persistIndex();
  return entry;
}

export function getMedia(id) {
  const entry = mediaIndex.get(id);
  if (!entry) return null;
  try {
    const buffer = fs.readFileSync(path.join(MEDIA_DIR, entry.file));
    return { ...entry, buffer };
  } catch {
    return null;
  }
}

export function rememberLastImage(userId, mediaId) {
  lastImageByUser.set(userId, mediaId);
}

export function getLastImageId(userId) {
  return lastImageByUser.get(userId) ?? null;
}

export function mediaUrl(id) {
  const base = String(process.env.CALLOUT_BASE_URL || process.env.PUBLIC_BASE_URL || '')
