import * as store from './store.js';

const CHECK_INTERVAL_MS = 60 * 1000;

export function startReminderScheduler(lineClient) {
  setInterval(() => {
    checkDueReminders(lineClient).catch((error) => console.error('Reminder check failed:', error.message));
  }, CHECK_INTERVAL_MS);

  console.log(`[reminder] scheduler started, checking every ${CHECK_INTERVAL_MS / 1000}s`);
}

async function checkDueReminders(lineClient) {
  const reminders = await store.listRecords('reminders');
  const now = new Date();

  for (const reminder of reminders) {
    if (reminder.status !== 'pending') continue;
    if (new Date(reminder.remindAt) > now) continue;

    try {
      await lineClient.pushMessage(reminder.userId, {
        type: 'text',
        text: `⏰ 提醒：${reminder.content}`,
      });
      await store.saveRecord('reminders', reminder.id, { ...reminder, status: 'sent', sentAt: store.nowIso() });
      console.log(`[reminder] sent to ${reminder.userId}: ${reminder.content}`);
    } catch (error) {
      console.error(`[reminder] push failed for ${reminder.userId}:`, error.message);
    }
  }
}

