// 極簡 vCard (.vcf) 解析器：LINE 沒有「聯絡人分享」的 webhook 事件，
// 但使用者可以把聯絡人匯出成 vCard 檔案再用 LINE 傳檔案給 bot，
// 這裡把 vCard 轉成跟 People API 工具相同的欄位格式。

export function parseVcards(text) {
  const unfolded = String(text ?? '')
    .replace(/\r\n/g, '\n')
    .replace(/\n[ \t]/g, ''); // 續行（folding）併回上一行

const cards = [];
  let current = null;

for (const rawLine of unfolded.split('\n')) {
    const line = rawLine.trim();
    if (!line) continue;

if (/^BEGIN:VCARD$/i.test(line)) {
      current = { name: '', emails: [], phones: [], organization: '', job_title: '', birthday: '', address: '', notes: '' };
      continue;
    }
    if (/^END:VCARD$/i.test(line)) {
      if (current && (current.name || current.emails.length || current.phones.length)) cards.push(current);
      current = null;
      continue;
    }
    if (!current) continue;

const colonIndex = line.indexOf(':');
    if (colonIndex < 0) continue;

const propPart = line.slice(0, colonIndex);
    let value = line.slice(colonIndex + 1);
    const [prop, ...paramParts] = propPart.split(';');
    const params = paramParts.join(';').toUpperCase();

if (params.includes('QUOTED-PRINTABLE')) value = decodeQuotedPrintable(value);
    value = value.replace(/\\n/gi, '\n').replace(/\\,/g, ',').replace(/\\;/g, ';').trim();
    if (!value) continue;

value = value.replace(/\\n/gi, '\n').replace(/\\,/g, ',').replace(/\\;/g, ';').trim();
    if (!value) continue;

switch (prop.toUpperCase()) {
      case 'FN':
        current.name = value;
        break;
      case 'N':
        if (!current.name) current.name = value.split(';').filter(Boolean).join('');
        break;
      case 'TEL':
        current.phones.push(value);
        break;
      case 'EMAIL':
        current.emails.push(value);
        break;
      case 'ORG':
        current.organization = value.split(';').filter(Boolean).join(' ');
        break;
      case 'TITLE':
        current.job_title = value;
        break;
      case 'BDAY':
        current.birthday = normalizeBday(value);
        break;
      case 'ADR':
        current.address = value.split(';').filter(Boolean).reverse().join('');
        break;
      case 'NOTE':
        current.notes = value;
        break;
      default:
        break;
    }
  }

return cards;
}

function normalizeBday(value) {
  const digits = value.replace(/[^\d]/g, '');
  if (digits.length === 8) return `${digits.slice(0, 4)}-${digits.slice(4, 6)}-${digits.slice(6, 8)}`;
  return value;
}

replace(/[^\d]/g, '');
  if (digits.length === 8) return `${digits.slice(0, 4)}-${digits.slice(4, 6)}-${digits.slice(6, 8)}`;
  return value;
}

function decodeQuotedPrintable(value) {
  try {
    const bytes = [];
    const cleaned = value.replace(/=\n/g, '');
    for (let i = 0; i < cleaned.length; i++) {
      if (cleaned[i] === '=' && i + 2 < cleaned.length + 1) {
        const hex = cleaned.slice(i + 1, i + 3);
        if (/^[0-9A-Fa-f]{2}$/.test(hex)) {
          bytes.push(parseInt(hex, 16));
          i += 2;
          continue;
        }
      }
      bytes.push(cleaned.charCodeAt(i));
    }
    return Buffer.from(bytes).toString('utf-8');
  } catch {
    return value;
  }
}

