import { createOAuthClient, getAuthUrl, saveTokens, tokenPath } from '../lib/googleAuth.js';

const port = Number(new URL(process.env.GOOGLE_OAUTH_REDIRECT_URI || 'http://localhost:4300/oauth2callback').port) || 4300;

async function main() {
  const client = createOAuthClient();
  if (!client) {
    console.error('請先在 .env 設定 GOOGLE_OAUTH_CLIENT_ID 與 GOOGLE_OAUTH_CLIENT_SECRET。');
    process.exit(1);
  }

const authUrl = getAuthUrl(client);
  console.log('請在瀏覽器打開以下網址，登入 Google 帳號並同意授權：');
  console.log('');
  console.log(authUrl);
  console.log('');

const server = http.createServer(async (req, res) => {
    const url = new URL(req.url, `http://localhost:${port}`);
    if (url.pathname !== '/oauth2callback') {
      res.writeHead(404);
      res.end();
      return;
    }

const code = url.searchParams.get('code');
    if (!code) {
      res.writeHead(400);
      res.end('缺少 code 參數，請重新整理授權網址再試一次。');
      return;
    }

try {
      const { tokens } = await client.getToken(code);
      saveTokens(tokens);

res.writeHead(200, { 'Content-Type': 'text/html; charset=utf-8' });
      res.end('<h1>授權成功</h1><p>已儲存 Google 授權資訊，回到終端機繼續上課。這個分頁可以關閉了。</p>');

res.writeHead(200, { 'Content-Type': 'text/html; charset=utf-8' });
      res.end('<h1>授權成功</h1><p>已儲存 Google 授權資訊，回到終端機繼續上課。這個分頁可以關閉了。</p>');

console.log(`授權成功，已將 token 儲存到 ${tokenPath()}`);
    } catch (error) {
      res.writeHead(500, { 'Content-Type': 'text/html; charset=utf-8' });
      res.end('<h1>授權失敗</h1><p>請查看終端機錯誤訊息並重試。</p>');
      console.error('授權失敗：', error.message);
    } finally {
      server.close();
    }
  });

server.listen(port, () => {
    console.log(`等待授權回呼於 http://localhost:${port}/oauth2callback ...`);
  });
}

main();

