function buildAgentMessages(answerText, trace) {
  const contacts = [];
  const seen = new Set();
  const pushContact = (contact) => {
    if (!contact || !contact.contact_id || seen.has(contact.contact_id)) return;
    seen.add(contact.contact_id);
    contacts.push(contact);
  };

const contactTools = new Set(['search_contacts', 'find_contact', 'list_contacts', 'get_contact', 'create_contact', 'update_contact']);
  for (const { name, result } of trace) {
    if (!result?.ok || !contactTools.has(name)) continue;
    if (Array.isArray(result.data?.contacts)) result.data.contacts.forEach(pushContact);
    if (result.data?.contact) pushContact(result.data.contact);
  }

const messages = [];
  if (contacts.length > 0) messages.push(contactCarousel(contacts));
  messages.push(msg.textMessage(answerText));
  return messages.slice(0, 5);
}

