async function reply(replyToken, messages, userId) {
  const list = (Array.isArray(messages) ? messages : [messages]).slice(0, 5);
  // 只有最後一則帶 quickReply，避免每則都塞
  ensureSingleQuickReply(list);
  try {
    return await lineClient.replyMessage(replyToken, list);
  } catch (error) {
    // 印出 LINE 回傳的詳細原因（例如 Flex 欄位錯誤），方便除錯
    const detail = error?.originalError?.response?.data;
    console.error('[reply] replyMessage 失敗：', error.statusCode || error.message, detail ? JSON.stringify(detail) : '');
    // reply token 過期或失敗時，改用 push 主動送給使用者（需要 userId）
    if (userId) {
      try {
        return await lineClient.pushMessage(userId, list);
      } catch (pushError) {
        const pushDetail = pushError?.originalError?.response?.data;
        console.error('[reply] pushMessage 後援也失敗：', pushError.statusCode || pushError.message, pushDetail ? JSON.stringify(pushDetail) : '');
      }
    }
    return undefined;
  }
}

function ensureSingleQuickReply(list) {
  let hasQuick = false;
  for (let i = list.length - 1; i >= 0; i--) {
    if (list[i].quickReply) {
      if (hasQuick) delete list[i].quickReply;
      hasQuick = true;
    }
  }
  if (!hasQuick && list.length > 0) list[list.length - 1].quickReply = msg.defaultQuickReply();
}

