    button { margin: 4px 4px 0 0; padding: 8px 12px; border: 0; border-radius: 6px; background: #2563eb; color: white; font-weight: 700; cursor: pointer; }
    a { color: #2563eb; }
    .actions { display: flex; flex-wrap: wrap; gap: 8px; }
    .muted { color: #64748b; }
  </style>
</head>
<body><main>${body}</main></body>
</html>`;
}

const port = Number(process.env.PORT || 3000);
app.listen(port, () => {
  console.log(`class06 personal secretary LINE bot listening on http://localhost:${port}`);
  startReminderScheduler(lineClient);
});
